            "options": {
              "axes": [
                "x",
                "y"
              ],
              "transpose": false,
              "normalized": false
            }
          },
          "layers": [
            {
              "mark": "point",
              "data": "series",
              "transform": [
                {
                  "kind": "filter",
                  "options": {
                    "column": "x",
                    "operation": "gte",
                    "value": -3
                  }
                },
                {
                  "kind": "sort",
                  "options": {
                    "columns": [
                      "x"
                    ],
                    "reverse": false
                  }
                }
              ],
              "layout": {
