                  "amplitude": 0.5,
                  "seed": 7
                }
              },
              "encodings": {
                "x": {
                  "column": "x",
                  "scale": "x"
                },
                "y": {
                  "value": 2.5
                },
                "fill": {
                  "value": "#102030"
                },
                "opacity": {
                  "value": 0.75
                }
