    "chart_theme",
    "chart_palette",
    "chart_table",
    "chart_column",
    "chart_row",
    "chart_cell",
    "chart_scale",
    "chart_domain",
    "chart_range",
    "chart_coordinate",
    "chart_layer",
    "chart_transform",
    "chart_layout",
    "chart_encoding",
    "chart_guide",
    "chart_tick",
    "chart_annotation",
    "chart_preset"
  ],
  "queries": [
    {
      "sql": "SELECT width,height,language FROM chart_document",
      "rows": [
        {
          "width": 120,
          "height": 80,
          "language": "de"
        }
      ]
    },
    {
      "sql": "SELECT ordinal,name FROM chart_column ORDER BY ordinal",
      "rows": [
        {
          "ordinal": 0,
          "name": "x"
        },
        {
          "ordinal": 1,
          "name": "x"
        },
        {
          "ordinal": 2,
          "name": "y"
        },
        {
          "ordinal": 3,
          "name": "note"
        },
        {
          "ordinal": 4,
          "name": "flag"
        },
        {
          "ordinal": 5,
          "name": "nil"
        }
      ]
    },
    {
      "sql": "SELECT ordinal,mark,data FROM chart_layer ORDER BY ordinal",
