          "data": "series"
        },
        {
          "ordinal": 1,
          "mark": "rule",
          "data": "unresolved-table"
        }
      ]
    },
    {
      "sql": "SELECT value_kind,COUNT(*) AS count FROM chart_cell GROUP BY value_kind ORDER BY value_kind",
      "rows": [
        {
          "value_kind": "boolean",
          "count": 2
        },
        {
          "value_kind": "null",
          "count": 2
        },
        {
          "value_kind": "number",
          "count": 4
        },
        {
          "value_kind": "string",
          "count": 4
        }
      ]
    }
  ],
